(window.SB_FULLC=window.SB_FULLC||{}).x={c:`[{"w":"xenophobe","d":"a person who fears or hates foreigners","s":"The history teacher warned that a xenophobe often spreads fear by blaming problems on people from other cultures.","p":"ZEE-nuh-fohb","o":"Greek","y":7,"bp":51,"m":"xenaphobe","nt":"Open","ps":"noun","t":["emotions","ogreek"]},{"w":"xenoglossy","d":"the supposed ability to speak or write a language one has never learned","s":"The researcher documented the strange case of xenoglossy in which the child spoke fluent ancient Greek without any prior exposure.","p":"zee-nuh-GLAW-see","o":"Greek","y":9,"bp":35,"sy":"zee.nuh.glaw.see","nt":"Open","ps":"noun","t":["wordwords","ogreek"]},{"w":"xylyl","d":"A univalent chemical radical derived from xylene by removal of one hydrogen atom, used in organic chemistry.","s":"The chemistry student carefully noted that the xylyl group in the compound was responsible for its distinctive reaction with the test reagent.","p":"ZY-lil","o":"Greek","y":8,"bp":60,"m":"xyly","sy":"xy.lyl","nt":"Advanced","ps":"noun","t":["chemistry","ogreek"]},{"w":"xiphias","d":"type genus of the Xiphiidae","s":"In his marine biology report, Dario noted that the xiphias, or swordfish, uses its long rostrum to slash through schools of smaller fish.","p":"ZIF-ee-us","o":"Latin","y":7,"bp":65,"m":"xiphius","sy":"xi.phi.as","nt":"Senior","ps":"noun","t":["olatin"]},{"w":"xylophone","d":"a percussion instrument with wooden bars tuned to produce a chromatic scale and with resonators; played with small mallets","s":"The kindergartner proudly played a simple tune on the colorful xylophone during the school recital.","p":"ZEYE-luh-fohn","o":"Greek","y":7,"bp":33,"m":"zylophone","sy":"zay.lah.fow.n","nt":"Open","ps":"noun","t":["music","ogreek"]},{"w":"xeroxed","d":"reproduce by xerography","s":"The secretary xeroxed thirty copies of the agenda before the morning meeting began.","p":"ZIH-rahkst","o":"Greek","y":6,"bp":30,"m":"zeroxed","sy":"zih.raa.kst","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"xeroxes","d":"a copy made by a xerographic printer","s":"The teacher made xeroxes of the original poem so every student could annotate their own copy.","p":"ZIH-rah-ksihz","o":"Greek","y":7,"bp":31,"m":"zeroxes","sy":"zih.raa.ksih.z","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"xeroxing","d":"reproduce by xerography","s":"He spent an hour xeroxing old newspaper articles for his history project on the space race.","p":"ZIH-rah-ksihng","o":"Greek","y":7,"bp":32,"m":"zeroxing","sy":"zih.raa.ksih.ng","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"xenophobia","d":"a fear of foreigners or strangers","s":"The community worked hard to overcome xenophobia by hosting cultural festivals that celebrated their diverse neighbors.","p":"zeh-nuh-FOH-bee-uh","o":"Greek","y":6,"bp":37,"m":"xenaphobia","sy":"zeh.nah.fow.biy.ah","nt":"Open","ps":"noun","t":["emotions","ogreek"]},{"w":"xenophobic","d":"suffering from xenophobia; having abnormal fear or hatred of the strange or foreign","s":"The xenophobic remarks made by the crowd shocked visitors who had traveled from abroad.","p":"zeh-nuh-FAH-bihk","o":"Greek","y":4,"bp":35,"m":"xenaphobic","sy":"zeh.nah.faa.bih.k","nt":"Open","ps":"adjective","t":["emotions","ogreek"]},{"w":"xenons","d":"a colorless odorless inert gaseous element occurring in the earth's atmosphere in trace amounts","s":"Scientists use xenons in specialized lighting because these noble gases produce a brilliant white glow.","p":"ZEE-nonz","o":"Greek","y":8,"bp":29,"m":"xeneons","sy":"xe.nons","nt":"Open","ps":"noun","t":["chemistry","colors","ogreek"]},{"w":"xeric","d":"being deficient in moisture","s":"Deserts provide xeric environments.","p":"ZEER-ik","o":"Greek","y":5,"bp":28,"m":"xerric","sy":"xer.ic","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"xeroma","d":"abnormal dryness of the conjunctiva and cornea of the eyes; may be due to a systemic deficiency of vitamin A","s":"The doctor diagnosed the patient with xeroma after she complained of persistently dry and irritated eyes.","p":"zeh-ROH-muh","o":"Greek","y":9,"bp":30,"m":"xeroama","sy":"xe.ro.ma","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"xis","d":"the cardinal number that is the sum of ten and one","s":"The philosopher wrote xis theorems on the board, asking students to prove each one before the end of class.","p":"EL-even","o":"Greek","y":5,"bp":28,"m":"xiss","nt":"Open","ps":"noun","t":["numbers","ogreek"]},{"w":"xmas","d":"a Christian holiday celebrating the birth of Christ; a quarter day in England, Wales, and Ireland","s":"The family hung a glittering Xmas wreath on the front door and strung colorful lights along the porch railing.","p":"KRIS-mus","o":"Greek","y":2,"bp":27,"m":"Xmass","nt":"Open","ps":"noun","t":["festivals","time","ogreek"]},{"w":"xmases","d":"a Christian holiday celebrating the birth of Christ; a quarter day in England, Wales, and Ireland","s":"After many Xmases spent apart, the whole family finally gathered together under one roof to celebrate.","p":"KRIS-mus-ez","o":"Greek","y":8,"bp":30,"m":"Xmasess","sy":"xmas.es","nt":"Open","ps":"noun","t":["festivals","time","ogreek"]},{"w":"xylem","d":"the woody part of plants: the supporting and water-conducting tissue, consisting primarily of tracheids and vessels","s":"Water travels from the roots to the leaves through the plant's xylem tissue.","p":"ZY-lum","o":"German","y":4,"bp":24,"m":"xylem is sometimes written xylum","sy":"xy.lem","nt":"Open","ps":"noun","t":["botany","body","onordic"]},{"w":"xylems","d":"the woody part of plants: the supporting and water-conducting tissue, consisting primarily of tracheids and vessels","s":"The biology students compared the xylems of different tree species under the microscope.","p":"ZY-lumz","o":"Greek","y":8,"bp":29,"m":"xylums","sy":"xy.lems","nt":"Open","ps":"noun","t":["body","botany","seafaring","ogreek"]},{"w":"xylene","d":"a colorless flammable volatile liquid hydrocarbon used as a solvent","s":"The laboratory technician carefully handled the xylene while wearing protective gloves.","p":"ZY-leen","o":"Greek","y":6,"bp":29,"m":"xyleen","sy":"xy.lene","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"xylol","d":"a colorless flammable volatile liquid hydrocarbon used as a solvent","s":"The chemist used xylol to dissolve the resin before applying it to the specimen slide.","p":"ZY-lawl","o":"Greek","y":7,"bp":28,"m":"xylole","sy":"xy.lol","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"xylols","d":"a colorless flammable volatile liquid hydrocarbon used as a solvent","s":"The storage cabinet contained several flammable xylols that required careful labeling.","p":"ZY-lawlz","o":"Greek","y":8,"bp":29,"m":"xyloles","sy":"xy.lols","nt":"Open","ps":"noun","t":["chemistry","colors","ogreek"]},{"w":"xylose","d":"a sugar extracted from wood or straw; used in foods for diabetics","s":"The nutritionist recommended xylose as a sweetener for her diabetic patient's diet.","p":"ZY-lohs","o":"Greek","y":6,"bp":29,"m":"xyloss","sy":"xy.lose","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"xyris","d":"chiefly American marsh plants, having usually yellow flowers","s":"Bright yellow xyris blossoms dotted the marshy edges of the Carolina wetland.","p":"ZY-ris","o":"Greek","y":7,"bp":28,"m":"xiris","sy":"xy.ris","nt":"Open","ps":"noun","t":["botany","flowers","ogreek"]},{"w":"xerogel","d":"A solid or semisolid material formed when the liquid is removed from a gel, leaving behind a dry, porous structure with a large surface area, used in science and industry.","s":"Scientists used a xerogel as an ultra-lightweight insulator in the spacecraft because it was nearly as light as air.","p":"ZEER-oh-jel","o":"Greek","y":8,"bp":65,"m":"xerogell","sy":"xe.ro.gel","nt":"Senior","ps":"noun","t":["ogreek"]},{"w":"xyloglyphy","d":"The art or craft of carving decorative designs or figures into wood, producing ornamental patterns or images on wooden surfaces.","s":"The museum curator explained that xyloglyphy was the ancient craft behind the intricate carvings on the temple doors.","p":"zy-LOH-glih-fee","o":"Greek","y":9,"bp":69,"m":"xyloglify","sy":"zy.loh.glih.fee","nt":"Senior","ps":"noun","t":["painting","ogreek"]},{"w":"xenon","d":"a colorless odorless inert gaseous element occurring in the earth's atmosphere in trace amounts","s":"Xenon gas is used in the bright headlights of many modern cars.","p":"ZEE-nahn","o":"Greek","y":3,"bp":28,"m":"zenon","sy":"ziy.naa.n","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"xerox","d":"a copy made by a xerographic printer","s":"Please xerox the permission slip so every student gets a copy.","p":"ZIH-rahks","o":"Greek","y":3,"bp":28,"m":"zerox","sy":"zih.raa.ks","nt":"Open","ps":"noun","t":["eponyms","ogreek","epgreek"]},{"w":"Xanthe","d":"A feminine given name of Greek origin meaning 'golden' or 'yellow-haired,' often associated with golden beauty in Greek mythology.","s":"In Greek mythology, Xanthe was one of the golden-haired sea nymphs who lived beneath the waves.","p":"ZA-ndh","o":"Greek","y":7,"bp":16,"sy":"zae.ndh","ps":"noun","t":["myth","colors","ogreek"]},{"w":"Xanthippe","d":"A proper name, most famously that of Socrates' wife, who was reputed to be quarrelsome and shrewish; now sometimes used as a common noun for a scolding or ill-tempered woman.","s":"History remembers Xanthippe as the sharp-tongued wife of the philosopher Socrates.","p":"zan-TIP-ee","o":"Greek","y":8,"bp":26,"sy":"xan.thippe","ps":"noun","t":["wordwords","ogreek"]},{"w":"xanthoastrocytoma","d":"A rare type of brain tumor composed of yellow-tinged star-shaped cells called astrocytes, typically found in young patients and usually slow-growing.","s":"The pathologist identified the brain tumor as a xanthoastrocytoma because of its yellow-tinged cells.","p":"zan-thoh-as-troh-sy-TOH-muh","o":"Greek","y":9,"bp":30,"sy":"xan.thoas.tro.cy.toma","ps":"noun","t":["body","disease","astronomy","ogreek"]},{"w":"xanthocarpous","d":"Bearing or producing yellow fruit; used to describe plants whose fruit is characteristically yellow in color.","s":"The xanthocarpous shrub produced bright yellow berries that birds loved to eat in autumn.","p":"zan-thoh-KAR-pus","o":"Greek","y":9,"bp":26,"sy":"xan.tho.car.pous","ps":"adjective","t":["botany","maps","spices","colors","ogreek"]},{"w":"xanthochromatic","d":"Having a yellow coloration or pigmentation; relating to or characterized by a yellow color in an organism or substance.","s":"The xanthochromatic feathers of the canary made it stand out among the other birds.","p":"zan-thoh-kroh-MAT-ik","o":"Greek","y":9,"bp":28,"sy":"xan.thochro.mat.ic","ps":"adjective","t":["painting","character","colors","ogreek"]},{"w":"xanthochromic","d":"Appearing yellow in color, especially used in medicine to describe cerebrospinal fluid that has a yellowish tint due to the presence of pigments.","s":"The cerebrospinal fluid appeared xanthochromic, hinting to the doctor that there had been bleeding.","p":"zan-thoh-KROH-mik","o":"Greek","y":9,"bp":23,"sy":"xan.thochromic","ps":"adjective","t":["body","pharmacy","painting","colors","ogreek"]},{"w":"xanthodont","d":"Having yellow teeth; describing a person or animal whose teeth are noticeably yellow in color.","s":"The old cartoon villain was drawn as xanthodont, with distinctly yellow teeth that looked menacing.","p":"ZAN-thoh-dont","o":"Greek","y":8,"bp":27,"sy":"xan.thodont","ps":"adjective","t":["body","animals","colors","ogreek"]},{"w":"xanthogen","d":"A chemical compound or radical that generates or produces yellow coloration, particularly the divalent group associated with xanthic acid.","s":"In chemistry class, we learned that xanthogen is a compound related to the xanthate group.","p":"ZAN-thoh-jen","o":"Greek","y":8,"bp":26,"sy":"xan.thogen","ps":"noun","t":["chemistry","colors","ogreek"]},{"w":"xanthogenic","d":"Producing or generating yellow color or yellow compounds; relating to the formation of xanthogen or xanthic substances.","s":"The xanthogenic reaction in the test tube produced a vivid yellow substance that surprised the students.","p":"zan-thoh-JEN-ik","o":"Greek","y":8,"bp":34,"sy":"xan.thogenic","ps":"adjective","t":["colors","ogreek"]},{"w":"xanthogranuloma","d":"A benign inflammatory growth or lesion that appears yellowish and contains granular tissue, often found in the skin or internal organs.","s":"The dermatologist told the parents that the small bump was a juvenile xanthogranuloma and harmless.","p":"zan-thoh-gran-yoo-LOH-muh","o":"Greek","y":9,"bp":30,"sy":"xan.thogran.u.lo.ma","ps":"noun","t":["body","disease","ogreek"]},{"w":"xanthopathy","d":"A disease or condition characterized by yellow discoloration of the skin or tissues, often caused by abnormal pigment deposits.","s":"The researcher studied xanthopathy to understand why the patient's skin had an unusual yellow tone.","p":"zan-THOP-uh-thee","o":"Greek","y":8,"bp":35,"sy":"xan.thopa.thy","ps":"noun","t":["body","disease","painting","character","ogreek"]},{"w":"xanthophobia","d":"An irrational and persistent fear of the color yellow, causing anxiety or distress when a person encounters yellow objects or environments.","s":"Her xanthophobia made her avoid yellow clothing, yellow cars, and even yellow food.","p":"zan-thoh-FOH-bee-uh","o":"Greek","y":9,"bp":38,"sy":"xan.tho.pho.bia","ps":"noun","t":["ecology","emotions","colors","ogreek"]},{"w":"xanthopicrite","d":"A variety of picrite rock that has a yellowish tint or coloration due to the presence of certain yellow minerals within its composition.","s":"The geologist collected a sample of xanthopicrite, noting its yellowish color among the dark rocks.","p":"zan-thoh-PIK-ryt","o":"Greek","y":9,"bp":25,"sy":"xan.thopi.crite","ps":"noun","t":["minerals","colors","ogreek"]},{"w":"xanthoproteic","d":"Describing a test in which proteins turn yellow with strong nitric acid.","s":"The xanthoproteic reaction turned the protein sample bright yellow when nitric acid was added.","p":"zan-thoh-proh-TEE-ik","o":"Greek","y":9,"bp":28,"sy":"xan.tho.pro.te.ic","ps":"adjective","t":["chemistry","ogreek"]},{"w":"xanthoprotein","d":"A yellow compound formed when proteins react with concentrated nitric acid, used as an indicator in chemical tests for the presence of certain amino acids.","s":"When the chemist added strong acid to the egg white, she observed the formation of xanthoprotein.","p":"zan-thoh-PROH-teen","o":"Greek","y":9,"bp":26,"sy":"xan.tho.pro.tein","ps":"noun","t":["chemistry","ogreek"]},{"w":"xanthorhamnin","d":"A yellow crystalline glycoside pigment extracted from the berries of buckthorn plants, historically used as a yellow dye.","s":"Scientists isolated xanthorhamnin from buckthorn plants to study its yellow pigment properties.","p":"zan-thoh-RAM-nin","o":"Greek","y":9,"bp":23,"sy":"xan.thorhamnin","ps":"noun","t":["botany","chemistry","minerals","spices","painting","ogreek"]},{"w":"xanthospermous","d":"Having yellow seeds; used to describe plant species whose seeds are characteristically yellow in color.","s":"The botanist noted that the xanthospermous plant produced seeds with a distinctly yellow coating.","p":"zan-thoh-SPUR-mus","o":"Greek","y":9,"bp":27,"sy":"xan.thos.per.mous","ps":"adjective","t":["botany","colors","ogreek"]},{"w":"xanthous","d":"of the color intermediate between green and orange in the color spectrum; of something resembling the color of an egg yolk","s":"The field guide described the xanthous flowers as brilliant yellow beacons attracting bees from far away.","p":"ZAN-thus","o":"Greek","y":9,"bp":27,"sy":"xan.t.hous","ps":"adjective","t":["spices","colors","ogreek"]},{"w":"xanthuria","d":"A medical condition in which the urine appears yellow or contains an abnormal excess of xanthine, a nitrogen-containing compound.","s":"The doctor diagnosed xanthuria after noticing the unusual yellow compounds present in the patient's urine.","p":"zan-THOOR-ee-uh","o":"Greek","y":9,"bp":26,"sy":"xan.thuria","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"xenial","d":"Of or relating to the friendly relationship between a host and a guest; characterized by hospitality and generous treatment of strangers or visitors.","s":"The xenial host greeted every traveler warmly and made sure they had food and a place to rest.","p":"ZEE-nee-ul","o":"Greek","y":8,"bp":18,"sy":"xe.nial","ps":"adjective","t":["body","character","ogreek"]},{"w":"xenoandrogen","d":"A foreign or synthetic substance, not produced naturally by the body, that mimics or acts like the male sex hormone androgen in biological systems.","s":"The environmental scientist warned that xenoandrogens in polluted water could disrupt hormones in fish.","p":"zee-noh-AN-droh-jen","o":"Greek","y":8,"bp":36,"sy":"xenoan.dro.gen","ps":"noun","t":["ogreek"]},{"w":"xenobiological","d":"Relating to the study of life forms or biological processes that are foreign to the Earth, such as extraterrestrial organisms or artificially introduced species.","s":"The science fiction story explored xenobiological discoveries when astronauts found life on another moon.","p":"zee-noh-by-oh-LOJ-ih-kul","o":"Greek","y":9,"bp":30,"sy":"xeno.bi.o.log.i.cal","ps":"adjective","t":["ogreek"]},{"w":"xenobiologist","d":"A scientist who studies organisms, life processes, or biological substances that are foreign to a particular environment, including potential extraterrestrial life.","s":"The xenobiologist spent her career imagining what life forms on other planets might look like.","p":"zee-noh-by-OL-oh-jist","o":"Greek","y":9,"bp":28,"sy":"xeno.bi.ol.o.gist","ps":"noun","t":["ecology","ogreek"]},{"w":"xenobiont","d":"A living organism that exists in or has been introduced into an environment foreign to its natural habitat, functioning as an alien entity within that ecosystem.","s":"A xenobiont is an organism that lives in a foreign environment, which fascinated the researchers.","p":"zee-noh-BY-ont","o":"Greek","y":8,"bp":26,"sy":"xeno.biont","ps":"noun","t":["ecology","ogreek"]},{"w":"xenobiotic","d":"Relating to a chemical substance that is foreign to a living organism or biological system, such as a synthetic drug, pollutant, or other man-made compound.","s":"Pesticides are xenobiotic chemicals because they are foreign to the natural systems of living organisms.","p":"zee-noh-by-OT-ik","o":"Greek","y":6,"bp":30,"sy":"xeno.bi.ot.ic","ps":"adjective","t":["pharmacy","chemistry","ogreek"]},{"w":"xenobiotically","d":"In a manner relating to or involving xenobiotics; describing how a foreign chemical substance interacts with or affects a living organism's biological systems.","s":"The chemical behaved xenobiotically in the fish's body, disrupting normal biological processes.","p":"zee-noh-by-OT-ik-lee","o":"Greek","y":9,"bp":30,"sy":"xeno.bi.ot.i.cal.ly","ps":"adverb","t":["chemistry","ogreek"]},{"w":"xenoblast","d":"A crystal in a metamorphic rock that lacks its own characteristic crystal form because it was forced to grow among surrounding minerals that were already present.","s":"The geologist identified a xenoblast embedded in the rock, noting its irregular crystal shape.","p":"ZEE-noh-blast","o":"Greek","y":8,"bp":25,"ps":"noun","t":["minerals","ogreek"]},{"w":"xenocentric","d":"Centered on or giving preference to foreign cultures, values, or practices over one's own; the opposite of ethnocentric in cultural perspective.","s":"Her xenocentric attitude led her to believe that every other culture's food was better than her own.","p":"zee-noh-SEN-trik","o":"Greek","y":8,"bp":35,"sy":"xeno.cen.tric","ps":"adjective","t":["ogreek"]},{"w":"xenocentrism","d":"The belief or tendency to regard foreign cultures, products, or customs as superior to one's own, often leading a person to prefer things from other countries.","s":"Xenocentrism can cause people to undervalue their own cultural traditions.","p":"zee-noh-SEN-triz-um","o":"Greek","y":8,"bp":36,"sy":"xeno.cen.trism","ps":"noun","t":["logic","ogreek"]},{"w":"Xenocrates","d":"An ancient Greek philosopher who led Plato's Academy and wrote on ethics and math.","s":"Xenocrates led the Academy in Athens after Speusippus and wrote extensively on philosophy.","p":"zeh-NOK-rah-teez","o":"Greek","y":7,"bp":26,"sy":"xenocrates","ps":"noun","t":["ancient","logic","numbers","ogreek"]},{"w":"xenoestrogen","d":"A chemical from outside the body that mimics a natural hormone and can upset the body's balance.","s":"Scientists warned that certain plastics release xenoestrogen that can interfere with the human hormonal system.","p":"zee-noh-EE-stroh-jen","o":"Greek","y":8,"bp":38,"sy":"xe.noe.stro.gen","ps":"noun","t":["chemistry","ogreek"]},{"w":"xenofree","d":"Describing a cell culture that contains no animal-derived or foreign materials.","s":"The lab used xenofree cell culture media to avoid contamination from animal-derived components.","p":"ZEE-noh-free","o":"Greek","y":9,"bp":24,"ps":"adjective","t":["animals","chemistry","ecology","ogreek"]},{"w":"xenogamous","d":"Describing a plant that reproduces by cross-fertilization between different individuals.","s":"The xenogamous plant relied on insects to carry pollen from one flower to another of a different plant.","p":"zeh-NOG-ah-mus","o":"Greek","y":9,"bp":29,"sy":"xenog.a.mous","ps":"adjective","t":["botany","ogreek"]},{"w":"xenogenesis","d":"the alternation of two or more different forms in the life cycle of a plant or animal","s":"The biology textbook explained xenogenesis as a life cycle where offspring look completely unlike their parents.","p":"zee-noh-JEN-eh-sis","o":"Greek","y":8,"bp":37,"sy":"xeno.gen.e.sis","ps":"noun","t":["animals","botany","ogreek"]},{"w":"xenogenous","d":"Originating from a foreign organism or substance from outside the body.","s":"The researcher noted that the infection was xenogenous, having originated from an outside source.","p":"zeh-NOJ-eh-nus","o":"Greek","y":9,"bp":26,"ps":"adjective","t":["ogreek"]},{"w":"xenography","d":"writing or copying out text in a foreign language or script","s":"The artist's xenography project documented foreign scripts and writing systems from around the world.","p":"zeh-NOG-rah-fee","o":"Greek","y":8,"bp":29,"sy":"xenog.ra.phy","ps":"noun","t":["wordwords","ogreek"]},{"w":"xenohormone","d":"a foreign chemical that behaves like the body's own natural signals","s":"The environmental toxin acted as a xenohormone, mimicking natural hormones in the body.","p":"zee-noh-HOR-mohn","o":"Greek","y":9,"bp":35,"sy":"xeno.hor.mone","ps":"noun","t":["chemistry","ogreek"]},{"w":"xenolinguistics","d":"The study of imagined alien or non-human languages and how they might work.","s":"Science fiction fans sometimes debate xenolinguistics when imagining how humans might communicate with aliens.","p":"zee-noh-ling-GWIS-tiks","o":"Greek","y":9,"bp":28,"sy":"xeno.lin.guis.tics","ps":"noun","t":["wordwords","ogreek"]},{"w":"xenology","d":"The scientific study of possible alien life, its biology and communication.","s":"Xenology examines the biology and behavior of extraterrestrial life forms in theoretical science.","p":"zeh-NOL-oh-jee","o":"Greek","y":8,"bp":27,"sy":"xenol.o.gy","ps":"noun","t":["economy","ogreek"]},{"w":"xenomorph","d":"A creature of strange, alien form, famously the monster in the Alien films.","s":"The creature in the movie was a classic xenomorph, with a body shape unlike anything found on Earth.","p":"ZEE-noh-morf","o":"Greek","y":6,"bp":25,"ps":"noun","t":["ogreek"]},{"w":"xenomorphic","d":"describing a crystal whose shape is set by surrounding minerals, not by itself","s":"The mineral had a xenomorphic texture because its crystals were squeezed into irregular shapes by surrounding rock.","p":"zee-noh-MOR-fik","o":"Greek","y":8,"bp":34,"sy":"xenomor.phic","ps":"adjective","t":["minerals","ogreek"]},{"w":"Xenophanes","d":"Greek philosopher (560-478 BC)","s":"Xenophanes challenged the Greek gods by arguing that humans create gods in their own image.","p":"zeh-NOF-ah-neez","o":"Greek","y":7,"bp":27,"sy":"xeno.phanes","ps":"noun","t":["logic","ogreek"]},{"w":"xenophilia","d":"A strong fondness for foreign people, cultures, and unfamiliar things.","s":"Her xenophilia drove her to collect art, food, and music from dozens of different countries.","p":"zee-noh-FIL-ee-ah","o":"Greek","y":9,"bp":27,"sy":"xenophil.ia","ps":"noun","t":["ogreek"]},{"w":"xenophobically","d":"In a way showing intense fear or hatred of foreigners and strangers.","s":"The crowd reacted xenophobically to the new immigrants, refusing to welcome them into the community.","p":"zee-noh-FOH-bik-lee","o":"Greek","y":9,"bp":29,"sy":"xeno.pho.bi.cal.ly","ps":"adverb","t":["emotions","ogreek"]},{"w":"Xenophon","d":"Greek general and historian; student of Socrates (430-355 BC)","s":"Xenophon wrote the Anabasis, recounting the dramatic retreat of Greek soldiers through Persia.","p":"ZEH-nuh-fuh-n","o":"Greek","y":4,"bp":27,"sy":"zeh.nah.fah.n","ps":"noun","t":["ogreek"]},{"w":"xenophonia","d":"A foreign or unusual accent in someone's speech.","s":"The speech therapist studied xenophonia in patients who developed foreign accents after brain injuries.","p":"zee-noh-FOH-nee-ah","o":"Greek","y":9,"bp":29,"sy":"xeno.pho.nia","ps":"noun","t":["wordwords","ogreek"]},{"w":"xenophthalmia","d":"Eye inflammation caused by a foreign object or irritant in the eye.","s":"The doctor diagnosed xenophthalmia after noticing the unusual eye inflammation caused by a foreign substance.","p":"zee-nof-THAL-mee-ah","o":"Greek","y":9,"bp":23,"sy":"xenoph.thalmia","ps":"noun","t":["disease","ogreek"]},{"w":"xenoreactive","d":"responding to cells or antigens from another species","s":"The patient's immune system was highly xenoreactive, attacking the transplanted organ from the pig.","p":"zee-noh-ree-AK-tiv","o":"Greek","y":9,"bp":36,"sy":"xenore.ac.tive","ps":"adjective","t":["music","ogreek"]},{"w":"xenotransplantation","d":"a surgical procedure in which tissue or whole organs are transfered from one species to another species","s":"Scientists are researching xenotransplantation using pig hearts to save patients waiting for human donors.","p":"zee-noh-tranz-plan-TAY-shun","o":"Greek","y":8,"bp":30,"sy":"xeno.trans.plan.ta.tion","ps":"noun","t":["body","ogreek"]},{"w":"xenotransplanted","d":"Describing tissue or an organ moved from one species into another.","s":"The xenotransplanted kidney functioned well in the lab animal for several weeks before rejection occurred.","p":"zee-noh-TRANZ-plan-ted","o":"Greek","y":9,"bp":29,"sy":"xeno.trans.plant.ed","ps":"adjective","t":["body","music","ogreek"]},{"w":"xenotropic","d":"Describing a virus that can multiply only in cells of a different species.","s":"The xenotropic virus could infect cells of different species but not those of its original host.","p":"zee-noh-TROP-ik","o":"Greek","y":8,"bp":27,"sy":"xenotrop.ic","ps":"adjective","t":["disease","numbers","ogreek"]},{"w":"xerically","d":"In a way suited to very dry conditions, as in desert-adapted plants.","s":"The desert plants adapted xerically, storing water and minimizing moisture loss in the scorching heat.","p":"ZEER-ih-klee","o":"Greek","y":9,"bp":28,"sy":"xeri.cal.ly","ps":"adverb","t":["animals","botany","ecology","landforms","ogreek"]},{"w":"xerochilia","d":"Constant dryness and chapping of the lips.","s":"The patient suffered from xerochilia, constantly applying lip balm to relieve the painful dryness.","p":"zeer-oh-KIL-ee-ah","o":"Greek","y":9,"bp":29,"sy":"xe.rochil.ia","ps":"noun","t":["body","ecology","character","ogreek"]},{"w":"xerodermia","d":"a mild form of ichthyosis characterized by abnormal dryness and roughness of the skin","s":"His xerodermia made his skin feel rough and scaly, especially during cold winter months.","p":"zeer-oh-DER-mee-ah","o":"Greek","y":9,"bp":30,"sy":"xe.ro.der.mia","ps":"noun","t":["body","character","ogreek"]},{"w":"xerogram","d":"An image produced by a dry, powder-and-static copying process instead of ink.","s":"The technician printed a xerogram of the document using the dry-process copying machine.","p":"ZEER-oh-gram","o":"Greek","y":8,"bp":27,"sy":"xe.ro.gram","ps":"noun","t":["physics","ogreek"]},{"w":"xerography","d":"forming an image by the action of light on a specially coated charged plate; the latent image is developed with powders that adhere only to electrically charged areas","s":"Edge enhancement is intrinsic in xerography.","p":"zeer-OG-rah-fee","o":"Greek","y":7,"bp":30,"sy":"xe.rog.ra.phy","ps":"noun","t":["physics","ogreek"]},{"w":"Xeroid","d":"Describing a habitat or organism suited to extremely dry conditions.","s":"Scientists classified the habitat as Xeroid because it shared characteristics with true desert environments.","p":"ZEER-oyd","o":"Greek","y":8,"bp":18,"sy":"xe.roid","ps":"adjective","t":["ecology","ogreek"]},{"w":"xeromammography","d":"A breast X-ray using a dry copying process to make clear images.","s":"Before digital imaging, xeromammography was used to detect tumors in breast tissue through a dry X-ray process.","p":"zeer-oh-mam-OG-rah-fee","o":"Greek","y":9,"bp":31,"sy":"xe.ro.mam.mog.ra.phy","ps":"noun","t":["body","ogreek"]},{"w":"xeromycteria","d":"Abnormal dryness inside the nose and its membranes, causing discomfort and hard breathing.","s":"The patient's xeromycteria caused persistent discomfort from chronic dryness inside the nasal passages.","p":"zeer-oh-mik-TEER-ee-ah","o":"Greek","y":9,"bp":38,"sy":"xe.romyc.te.ria","ps":"noun","t":["body","ogreek"]},{"w":"xerophagia","d":"The practice of eating only dry foods, sometimes for religious fasting.","s":"Ancient monks practiced xerophagia as a form of religious fasting, eating only dry bread and water.","p":"zeer-oh-FAY-jee-ah","o":"Greek","y":9,"bp":29,"sy":"xe.ropha.gia","ps":"noun","t":["dishes","religion","ogreek"]},{"w":"xerophagy","d":"A strict religious diet of only dry, uncooked food and water.","s":"Xerophagy was observed in the monastery during Lent, with monks surviving on minimal dry food.","p":"zeer-OF-ah-jee","o":"Greek","y":8,"bp":26,"sy":"xe.rophagy","ps":"noun","t":["religion","festivals","ogreek"]},{"w":"xerophilic","d":"Describing an organism that thrives in extremely dry conditions.","s":"Xerophilic bacteria thrive in extremely dry environments where most other organisms cannot survive.","p":"zeer-oh-FIL-ik","o":"Greek","y":8,"bp":27,"sy":"xe.rophilic","ps":"adjective","t":["botany","ogreek"]},{"w":"xerophthalmia","d":"abnormal dryness of the conjunctiva and cornea of the eyes; may be due to a systemic deficiency of vitamin A","s":"Vitamin A deficiency can cause xerophthalmia, leading to severe dryness and even blindness if untreated.","p":"zeer-of-THAL-mee-ah","o":"Greek","y":9,"bp":25,"sy":"xe.roph.thalmia","ps":"noun","t":["ogreek"]},{"w":"xerostoma","d":"A condition of persistent mouth dryness from too little saliva.","s":"The patient's xerostoma made it difficult to swallow food without drinking water first.","p":"zeer-oh-STOH-mah","o":"Greek","y":9,"bp":28,"sy":"xe.ros.toma","ps":"noun","t":["body","disease","character","ogreek"]},{"w":"xerotripsis","d":"a treatment that rubs the dry skin without oils, water, or lubricants","s":"The ancient physician used xerotripsis to stimulate circulation in the patient's dry, stiff limbs.","p":"zeer-oh-TRIP-sis","o":"Greek","y":8,"bp":35,"sy":"xe.rotrip.sis","ps":"noun","t":["body","physics","ogreek"]},{"w":"Xerxes","d":"A powerful ancient Persian king who invaded Greece in the Greco-Persian Wars.","s":"Xerxes led a massive Persian army across a bridge of boats to invade Greece.","p":"ZER-ksee-z","o":"Greek","y":4,"bp":18,"sy":"zer.ksiy.z","ps":"noun","t":["war","ancient","royalty","ogreek"]},{"w":"xiphioid","d":"Shaped like a sword; long, narrow, and pointed.","s":"The biologist noted the xiphioid shape of the swordfish's elongated snout.","p":"ZIF-ee-oyd","o":"Greek","y":9,"bp":24,"ps":"adjective","t":["body","animals","war","ogreek"]},{"w":"xiphoid","d":"The small, sword-shaped tip at the lower end of the breastbone.","s":"The doctor located the xiphoid process at the lower tip of the sternum during the examination.","p":"ZIF-oyd","o":"Greek","y":7,"bp":17,"ps":"noun","t":["war","ogreek"]},{"w":"xiphoiditis","d":"Inflammation of the xiphoid process, the small cartilaginous extension at the lower end of the breastbone, causing chest or upper abdominal pain.","s":"After the fall, the gymnast was diagnosed with xiphoiditis, causing sharp chest pain.","p":"zif-oy-DY-tis","o":"Greek","y":9,"bp":34,"sy":"xiphoidi.tis","ps":"noun","t":["disease","ogreek"]},{"w":"xiphos","d":"An ancient Greek short sword with a double-edged, leaf-shaped blade, commonly used by infantry soldiers in close combat.","s":"The Spartan warrior drew his xiphos when his spear shattered in battle.","p":"ZIF-os","o":"Greek","y":8,"bp":16,"ps":"noun","t":["botany","war","ancient","ogreek"]},{"w":"xylivorous","d":"Describing an organism, such as certain insects or fungi, that feeds on or consumes wood as its primary source of nutrition.","s":"The xylivorous termites had hollowed out the entire wooden beam within a year.","p":"zy-LIV-uh-rus","o":"Greek","y":9,"bp":29,"sy":"xyliv.o.rous","ps":"adjective","t":["insects","botany","ogreek"]},{"w":"xylocarpous","d":"Describing a plant that produces fruits with a hard, woody outer shell or texture, making them unusually firm and durable.","s":"The xylocarpous fruits of the tree were so hard that animals couldn't crack them open.","p":"zy-loh-KAR-pus","o":"Greek","y":9,"bp":37,"sy":"xy.lo.car.pous","ps":"adjective","t":["botany","spices","ogreek"]},{"w":"xylogen","d":"The woody tissue of a plant, particularly the xylem, which is responsible for transporting water and forming the structural wood of the plant.","s":"Scientists studied how xylogen forms during the early growth stages of young trees.","p":"ZY-luh-jen","o":"Greek","y":8,"bp":20,"sy":"xy.lo.gen","ps":"noun","t":["body","botany","ogreek"]},{"w":"xylogenesis","d":"The biological process by which woody tissue, or xylem, is formed in plants, giving trees and shrubs their hard, durable structure.","s":"Understanding xylogenesis helps researchers develop faster-growing timber trees.","p":"zy-loh-JEN-uh-sis","o":"Greek","y":8,"bp":40,"sy":"xy.lo.ge.n.e.sis","ps":"noun","t":["body","botany","flowers","ogreek"]},{"w":"xylography","d":"The art or technique of engraving designs onto wood blocks and printing from them, one of the earliest forms of printmaking in human history.","s":"The museum displayed beautiful examples of xylography, where artists carved images into wooden blocks.","p":"zy-LOG-ruh-fee","o":"Greek","y":8,"bp":30,"sy":"xy.log.ra.phy","ps":"noun","t":["painting","ogreek"]},{"w":"xyloid","d":"Resembling or having the properties of wood; possessing a woody texture, appearance, or composition similar to natural timber.","s":"The fossil had a xyloid texture, resembling the grain of ancient wood.","p":"ZY-loyd","o":"Greek","y":8,"bp":18,"sy":"xy.loid","ps":"adjective","t":["ogreek"]},{"w":"xylology","d":"The scientific study of the structure, properties, and characteristics of wood, including its cellular composition and practical applications.","s":"Her specialty in xylology helped the conservation team identify the rare wood used in the antique desk.","p":"zy-LOL-uh-jee","o":"Greek","y":8,"bp":28,"sy":"xy.lol.o.gy","ps":"noun","t":["ogreek"]},{"w":"xylophagia","d":"The habit or condition of eating wood, practiced by certain insects, larvae, and animals as a means of obtaining nutrition or burrowing.","s":"The rare condition of xylophagia caused the child to compulsively chew on pencils and sticks.","p":"zy-loh-FAY-jee-uh","o":"Greek","y":9,"bp":29,"sy":"xy.lopha.gia","ps":"noun","t":["animals","insects","ogreek"]},{"w":"xylophilous","d":"Describing an organism, especially a plant or insect, that thrives in or shows a strong preference for living in or on wood.","s":"The xylophilous beetle thrives only in the deep bark of old-growth oak trees.","p":"zy-LOF-uh-lus","o":"Greek","y":9,"bp":34,"sy":"xy.lophilous","ps":"adjective","t":["insects","botany","ogreek"]},{"w":"xylophonelike","d":"Resembling or characteristic of a xylophone in appearance, structure, or sound, particularly having a series of graduated wooden bars that produce musical tones.","s":"The marimba produces a xylophonelike tone that fills the concert hall with warmth.","p":"ZY-luh-fohn-lyk","o":"Greek","y":9,"bp":26,"sy":"xy.lo.phone.like","ps":"adjective","t":["music","ogreek"]},{"w":"xyloquinone","d":"A chemical compound of the quinone family derived from wood or woody plant material, studied for its properties in organic chemistry and biochemistry.","s":"Researchers isolated xyloquinone from wood samples to study its chemical properties.","p":"zy-loh-KWIN-ohn","o":"Greek","y":9,"bp":35,"sy":"xy.lo.quinone","ps":"noun","t":["botany","chemistry","kinship","ogreek"]},{"w":"xylorcin","d":"A crystalline chemical compound obtained from certain wood-derived substances, related to orcinol, and used in chemical analysis and research.","s":"The chemist extracted xylorcin from wood tar during the laboratory experiment.","p":"ZY-lor-sin","o":"Greek","y":8,"bp":25,"sy":"xy.lorcin","ps":"noun","t":["chemistry","minerals","ogreek"]},{"w":"xylorimba","d":"A large percussion instrument that combines the range and resonance of a xylophone with the extended lower notes of a marimba, used in orchestral and concert music.","s":"The percussionist played a haunting melody on the xylorimba, blending the range of xylophone and marimba.","p":"zy-loh-RIM-buh","o":"Greek","y":9,"bp":28,"sy":"xy.lorim.ba","ps":"noun","t":["music","ogreek"]},{"w":"xylotomist","d":"A specialist who prepares and studies thin sections of wood under a microscope in order to examine its cellular structure and identify different species of timber.","s":"The xylotomist carefully prepared thin wood slices to examine under the microscope.","p":"zy-LOT-uh-mist","o":"Greek","y":8,"bp":29,"sy":"xy.lo.tomist","ps":"noun","t":["tools","ogreek"]},{"w":"xylotomy","d":"The scientific technique of cutting and preparing thin sections of wood for microscopic examination in order to study its internal structure and grain.","s":"Through xylotomy, the scientist identified the exact species of tree used to build the ancient ship.","p":"zy-LOT-uh-mee","o":"Greek","y":8,"bp":28,"sy":"xy.lo.to.my","ps":"noun","t":["ogreek"]},{"w":"xyster","d":"A surgical instrument with a rough or serrated edge used to scrape bone tissue, historically employed by surgeons during medical procedures.","s":"The surgeon used a xyster to scrape away the diseased bone tissue during the procedure.","p":"ZIS-ter","o":"Greek","y":8,"bp":18,"sy":"xys.ter","ps":"noun","t":["body","music","ogreek"]},{"w":"xystus","d":"In ancient Roman architecture, a long covered walkway or garden portico used for exercise and strolling, often lined with trees or ornamental plants.","s":"The Roman villa's xystus was lined with trimmed hedges and fragrant flowers for evening walks.","p":"ZIS-tus","o":"Greek","y":8,"bp":18,"sy":"xys.tus","ps":"noun","t":["botany","flowers","buildings","ancient","ogreek"]},{"w":"xanthein","d":"The water-soluble portion of the yellow pigment found in certain flowers and plants, responsible for producing yellow coloration in petals and other plant tissues.","s":"The chemist isolated xanthein from the yellow flower petals to study its pigment structure.","p":"ZAN-thee-in","o":"French","y":8,"bp":19,"sy":"xan.thein","ps":"noun","t":["body","botany","flowers","painting","colors","ofrench"]},{"w":"xanthophyllic","d":"Relating to or characterized by xanthophyll, the yellow pigment found in plant leaves and other organisms that becomes visible in autumn when green chlorophyll breaks down.","s":"The xanthophyllic leaves turned a brilliant gold as autumn arrived in the valley.","p":"zan-thoh-FIL-ik","o":"French","y":9,"bp":38,"sy":"xan.tho.phyl.lic","ps":"adjective","t":["botany","painting","character","time","ofrench"]},{"w":"xenoantigen","d":"An antigen that originates from a different species and triggers an immune response when introduced into the body of another organism, such as during organ transplantation.","s":"The lab researchers studied the xenoantigen to understand why the patient's body rejected the transplanted organ.","p":"zee-noh-AN-tih-jen","o":"French","y":8,"bp":34,"sy":"xenoanti.gen","ps":"noun","t":["music","ofrench"]},{"w":"xenolithic","d":"Relating to or containing xenoliths, which are fragments of foreign rock that become enclosed within a larger body of igneous rock during volcanic activity or magma movement.","s":"The geologist was excited to find a xenolithic fragment embedded in the volcanic rock sample.","p":"zee-noh-LITH-ik","o":"French","y":8,"bp":29,"sy":"xeno.lith.ic","ps":"adjective","t":["minerals","ofrench"]},{"w":"xeronic","d":"Relating to or characteristic of extremely dry conditions or environments, especially used to describe chemical or biological processes that occur under arid or desiccated circumstances.","s":"The xeronic conditions of the desert made it nearly impossible for most plants to survive.","p":"zeh-RON-ik","o":"French","y":8,"bp":20,"sy":"xe.ron.ic","ps":"adjective","t":["chemistry","ecology","ofrench"]},{"w":"xylemic","d":"Relating to or involving xylem, the vascular tissue in plants responsible for transporting water and dissolved minerals from the roots upward through the stem and leaves.","s":"The xylemic tissue in the plant stem carried water upward from the roots to the leaves.","p":"zy-LEE-mik","o":"French","y":8,"bp":17,"ps":"adjective","t":["body","botany","minerals","ofrench"]},{"w":"xylonic","d":"Relating to an organic acid made by oxidizing xylose, a wood sugar found in plant cell walls.","s":"The chemist produced xylonic acid from wood sugars during the fermentation experiment.","p":"zy-LON-ik","o":"French","y":8,"bp":19,"sy":"xy.lonic","ps":"adjective","t":["botany","chemistry","ofrench"]},{"w":"xylophagic","d":"Feeding on or consuming wood; describes insects, fungi, or other organisms that digest and derive nutrition from woody plant material or timber.","s":"The xylophagic beetles bored deep tunnels into the old oak tree, slowly destroying it.","p":"zy-loh-FAJ-ik","o":"French","y":8,"bp":29,"sy":"xy.lophag.ic","ps":"adjective","t":["insects","botany","ofrench"]},{"w":"xylophonic","d":"Relating to or resembling the sound or quality of a xylophone, a percussion instrument with wooden bars struck by mallets to produce bright, resonant musical tones.","s":"The xylophonic notes rang out clearly across the school auditorium during the talent show.","p":"zy-loh-FON-ik","o":"French","y":8,"bp":30,"sy":"xy.lo.phon.ic","ps":"adjective","t":["music","ofrench"]},{"w":"xylophonically","d":"In a manner resembling or characteristic of the xylophone, describing music or sound that has the bright, percussive, and wooden tonal quality of that instrument.","s":"She played the melody xylophonically, each wooden bar producing a crisp, bright tone.","p":"zy-loh-FON-ik-lee","o":"French","y":9,"bp":30,"sy":"xy.lo.phon.i.cal.ly","ps":"adverb","t":["music","ofrench"]},{"w":"xylotypography","d":"The art or process of printing text or images using engraved wooden blocks, an early form of printing that preceded movable type and was widely used in East Asia and medieval Europe.","s":"Before modern printing, xylotypography allowed printers to carve entire pages of text into wooden blocks.","p":"zy-loh-ty-POG-rah-fee","o":"French","y":9,"bp":30,"sy":"xy.lo.ty.pog.ra.phy","ps":"noun","t":["painting","ofrench"]},{"w":"xylemless","d":"Lacking or devoid of xylem, the vascular tissue in plants responsible for transporting water and nutrients from roots to leaves.","s":"The parasitic plant was xylemless, depending entirely on its host for water transport.","p":"ZY-lem-les","o":"German","y":8,"bp":22,"sy":"xylem.less","ps":"adjective","t":["body","botany","onordic"]},{"w":"xylemlike","d":"Resembling or functioning similarly to xylem, the plant tissue that conducts water and dissolved minerals upward through the stem.","s":"The scientist discovered a xylemlike structure in the fossilized plant that helped it carry nutrients.","p":"ZY-lem-lyk","o":"German","y":9,"bp":22,"sy":"xylem.like","ps":"adjective","t":["body","botany","minerals","onordic"]},{"w":"xacuti","d":"A rich, complex curry dish from the Goa region of India, made with a spiced coconut-based sauce that typically includes roasted spices, red chilies, and meat such as chicken or lamb.","s":"The chef stirred the fragrant xacuti, a rich Goan curry made with roasted coconut and whole spices.","p":"sha-KOO-tee","o":"Konkani","y":8,"bp":15,"sy":"xa.cu.ti","ps":"noun","t":["culinary","dishes","spices"]},{"w":"xanthotoxin","d":"A naturally occurring chemical compound, also called methoxsalen, found in certain plants and used medically to treat skin conditions such as psoriasis and vitiligo.","s":"Scientists studied xanthotoxin from the plant extract for its potential use in treating skin conditions.","p":"zan-thoh-TOK-sin","o":"Latin","y":8,"bp":37,"sy":"xan.tho.tox.in","ps":"noun","t":["body","botany","chemistry","olatin"]},{"w":"Xenaphile","d":"A devoted fan or enthusiast of the television series Xena: Warrior Princess, or someone with a strong admiration for the character Xena.","s":"As a devoted Xenaphile, she owned every action figure and collector's item from the TV series.","p":"ZEE-nuh-fyl","o":"Latin","y":9,"bp":26,"sy":"xe.naphile","ps":"noun","t":["royalty","olatin"]},{"w":"xenodiagnosis","d":"A diagnostic method in which a laboratory-raised, uninfected host organism is allowed to feed on a patient and then examined to detect the presence of a pathogen or parasite.","s":"The researchers used xenodiagnosis, allowing uninfected insects to feed on a patient to detect the parasite.","p":"zen-oh-dy-ag-NOH-sis","o":"Latin","y":9,"bp":28,"sy":"xen.odi.ag.no.sis","ps":"noun","t":["body","disease","olatin"]},{"w":"xenoparasite","d":"A parasite that infects an organism other than its usual or natural host, living on or within a foreign or unusual host species.","s":"The zoologist explained that a xenoparasite is one that has jumped to a host species it does not normally infect.","p":"zen-oh-PAIR-uh-syt","o":"Latin","y":9,"bp":36,"sy":"xenopar.a.site","ps":"noun","t":["olatin"]},{"w":"xerophile","d":"plant adapted for life with a limited supply of water; compare hydrophyte and mesophyte","s":"The cactus is a classic xerophile, thriving in the desert where most plants would quickly wither and die.","p":"ZEER-oh-fyl","o":"Latin","y":9,"bp":26,"sy":"xe.rophile","ps":"noun","t":["botany","olatin"]},{"w":"xeroxlore","d":"The body of jokes, cartoons, urban legends, and informal stories that spread widely through photocopying and office culture before the digital age.","s":"The teacher collected examples of xeroxlore, like funny copied office memos that had been passed around for years.","p":"ZEER-oks-lor","o":"Latin","y":9,"bp":28,"sy":"xe.rox.lore","ps":"noun","t":["poetry","myth","olatin"]},{"w":"Xerxean","d":"Relating to or characteristic of Xerxes I, the powerful Persian king known for his massive military campaigns and the invasion of ancient Greece.","s":"The general's Xerxean ambition led him to assemble an army so vast it darkened the horizon.","p":"ZURK-see-un","o":"Latin","y":8,"bp":19,"sy":"xerx.ean","ps":"adjective","t":["politics","war","ancient","royalty","olatin"]},{"w":"Xhosan","d":"Relating to or characteristic of the Xhosa people, their Bantu language noted for its distinctive click consonants, or their culture in southern Africa.","s":"The Xhosan click language fascinated the linguistics students who tried to mimic its unique sounds.","p":"KOH-sun","o":"Latin","y":8,"bp":16,"sy":"xhosan","ps":"adjective","t":["wordwords","olatin"]},{"w":"Xibalban","d":"Relating to Xibalba, the fearsome underworld realm in ancient Maya mythology, ruled by death gods and associated with darkness, disease, and trials of the dead.","s":"The archaeologist described the carvings as Xibalban in origin, depicting the Maya underworld's dark rulers.","p":"shee-BAHL-bun","o":"Latin","y":8,"bp":25,"sy":"xibal.ban","ps":"adjective","t":["disease","myth","law","ancient","olatin"]},{"w":"Ximenean","d":"Relating to or characteristic of Francisco Jiménez de Cisneros, known as Ximenes, the powerful Spanish cardinal and statesman of the late fifteenth and early sixteenth centuries.","s":"The strict Ximenean inquisitor reviewed every document with cold, unyielding precision.","p":"hee-meh-NEE-un","o":"Latin","y":8,"bp":25,"sy":"xime.nean","ps":"adjective","t":["time","olatin"]},{"w":"Xochicalcan","d":"Relating to Xochicalco, the pre-Columbian archaeological site and ancient city in central Mexico known for its ceremonial architecture and astronomical significance.","s":"The Xochicalcan ruins revealed a complex calendar system that rivaled those of other ancient Mesoamerican cities.","p":"soh-chee-KAHL-kun","o":"Latin","y":9,"bp":35,"sy":"xochi.cal.can","ps":"adjective","t":["astronomy","buildings","ancient","olatin"]},{"w":"Xochimilcan","d":"Relating to Xochimilco, the ancient city and borough of Mexico City famous for its network of canals, floating gardens called chinampas, and rich indigenous heritage.","s":"The Xochimilcan farmers have cultivated floating garden islands called chinampas for hundreds of years.","p":"soh-chee-MEEL-kun","o":"Latin","y":9,"bp":35,"sy":"xochim.il.can","ps":"adjective","t":["ancient","olatin"]},{"w":"xyloplastic","d":"Relating to or describing the shaping or molding of wood into forms, or materials that combine wood fiber with a plastic or moldable substance.","s":"The craftsman used xyloplastic techniques to mold softened wood into elegant curved furniture panels.","p":"zy-loh-PLAS-tik","o":"Latin","y":8,"bp":37,"sy":"xy.lo.plas.tic","ps":"adjective","t":["olatin"]},{"w":"Xiaomin","d":"A Chinese given name meaning 'little people' or 'common people,' composed of the characters xiao (small, little) and min (people, citizens), often used to refer to ordinary folk in Chinese society.","s":"Xiaomin carefully practiced her calligraphy strokes every evening after school.","p":"SHYOW-min","o":"Mandarin Chinese","y":9,"bp":15,"sy":"xi.aomin","ps":"noun","t":["politics","oeastasia"]},{"w":"xenopid","d":"Of or belonging to the family Xenopidae, a group of tongueless aquatic frogs native to Africa, including the clawed frogs of the genus Xenopus.","s":"The biology class observed a xenopid frog swimming gracefully in the aquarium tank.","p":"ZEE-nuh-pid","o":"French","y":8,"bp":17,"ps":"adjective","t":["animals","marine","kinship","ofrench"]},{"w":"xiphosurid","d":"Of or relating to the order Xiphosura, which includes horseshoe crabs, ancient marine arthropods characterized by a hard shell and a long, sword-like tail spine.","s":"The horseshoe crab is a xiphosurid and has barely changed in millions of years.","p":"zif-oh-SYOOR-id","o":"French","y":8,"bp":27,"sy":"xipho.surid","ps":"adjective","t":["body","animals","character","war","ancient","ofrench"]},{"w":"xynisteri","d":"The most widely grown white grape variety native to Cyprus, used to produce crisp, dry white wines with bright acidity and flavors of citrus and green apple.","s":"The sommelier recommended a bottle of xynisteri, a crisp white wine native to Cyprus.","p":"ksee-nee-STEH-ree","o":"Modern Greek","y":9,"bp":26,"sy":"xynis.teri","ps":"noun","t":["spices","ogreek"]},{"w":"Xenaverse","d":"The fictional universe of the television series Xena: Warrior Princess, encompassing its characters, storylines, settings, and the broader mythology shared with its spin-off and related shows.","s":"Devoted fans mapped every character connection in the Xenaverse across all six seasons of the show.","p":"ZEE-nuh-vurs","o":"French","y":9,"bp":28,"sy":"xe.na.verse","ps":"noun","t":["astronomy","poetry","myth","royalty","ofrench"]},{"w":"xyrospasm","d":"A muscle spasm or involuntary convulsion experienced during shaving, typically caused by irritation of the skin or an underlying nervous reaction to the razor's motion.","s":"The barber's hand trembled with xyrospasm, making every shave a nerve-wracking experience for customers.","p":"ZY-roh-spaz-um","o":"French","y":8,"bp":26,"sy":"xy.rospasm","ps":"noun","t":["body","ofrench"]},{"w":"xeraphim","d":"A former silver coin used in Portuguese India, equal to a specific fraction of a rupee and used in trade and commerce along the western coast of India.","s":"The historian displayed an old xeraphim coin from Portuguese Goa in the museum case.","p":"ZAIR-ah-fim","o":"Portuguese","y":8,"bp":14,"ps":"noun","t":["waterways","economy","numbers","colors","oiberian"]},{"w":"xochinacaztli","d":"A Nahuatl term for the ear-shaped flower of a tropical tree used by the Aztecs as a flavoring for chocolate drinks and in ritual offerings; also called the flower ear.","s":"The ancient Aztec manuscript described xochinacaztli as a flower used in sacred offerings and ceremonies.","p":"soh-chee-nah-KAHZ-tlee","o":"nah","y":9,"bp":31,"sy":"xochi.nacaztli","ps":"noun","t":["flowers","religion","ancient"]},{"w":"xocomecatlite","d":"A rare copper tellurite mineral, found in very few locations worldwide, notable for its striking green color and its unusual chemical composition involving tellurium.","s":"The mineralogist carefully catalogued a rare sample of xocomecatlite found in the Mexican copper mine.","p":"shoh-koh-meh-KAT-lyt","o":"nah","y":9,"bp":33,"sy":"xo.come.catlite","ps":"noun","t":["chemistry","minerals","colors"]},{"w":"xanthosis","d":"an abnormal yellow discoloration of the skin","y":8,"bp":53,"nt":"Senior","ps":"noun","t":["body"]}]`,h:'[{"w":"xylophagous","d":"feeding entirely on the tissues of wood","s":"Termites are highly xylophagous bugs that chew through fallen logs to help recycle the forest floor.","p":"zy-LOF-uh-guhs","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"adjective","t":["championship","diet","insects","body","ogreek"],"m":"xylofagous","sy":"xy.loph.a.gous"},{"w":"xiaolongbao","d":"A type of steamed bun filled with a savory broth and tender filling, carefully eaten to avoid spilling the soup inside.","s":"We ordered a bamboo basket of fresh xiaolongbao, marveling at how the warm soup stayed inside the thin dough.","p":"shau-long-BAU","o":"Mandarin Chinese","y":9,"bp":50,"nt":"Open","ps":"noun","t":["championship","food","cooking","culinary","dishes","oeastasia"],"m":"xialongbao","sy":"xi.ao.long.bao"},{"w":"xoloitzcuintli","d":"a rare breed of hairless dog native to Mexico","s":"The ancient clay statue perfectly captured the wrinkled face of a xoloitzcuintli.","p":"show-low-eets-KWEENT-lee","o":"Nahuatl","y":9,"bp":60,"nt":"Open","ps":"noun","t":["championship","animals","dogs","oworld"],"m":"zoloitzcuintli","sy":"xo.lo.itz.cuin.tli"},{"w":"xeriscaping","d":"A style of landscape design requiring little or no extra watering or other maintenance, used in arid regions.","s":"The family saved thousands of gallons of water each year by replacing their lawn with beautiful desert xeriscaping.","p":"ZEER-ih-skay-ping","o":"Greek","y":7,"bp":30,"nt":"Open","ps":"noun","t":["championship","agriculture","landscaping","ogreek"],"m":"zeriscaping","sy":"xe.ri.scap.ing"},{"w":"xanthophyll","d":"A yellow pigment found in plant leaves that helps them safely absorb light energy.","s":"In the autumn, the green color fades from the trees and the yellow xanthophyll finally becomes visible.","p":"ZAN-thuh-fil","o":"Greek","y":8,"bp":40,"nt":"Open","ps":"noun","t":["championship","biochemistry","plants","botany","physics","painting","ogreek"],"m":"xanthophyl","sy":"xan.tho.phyll"},{"w":"xylographic","d":"Of pictures or books printed from a carved wooden block.","s":"The earliest playing cards were xylographic, cut and inked one block at a time.","p":"zy-luh-GRAF-ik","o":"Greek","y":8,"bp":58,"nt":"Open","ps":"adjective","t":["championship","printmaking","ogreek"],"m":"zylographic","sy":"xy.lo.graph.ic"},{"w":"xenolith","d":"A lump of older rock caught up and carried inside a newer one.","s":"A dark xenolith sat in the granite like a plum in a pudding.","p":"ZEN-uh-lith","o":"Greek","y":8,"bp":57,"nt":"Open","ps":"noun","t":["championship","petrology","minerals","ogreek"],"m":"zenolith","sy":"xen.o.lith"},{"w":"xerophyte","d":"A plant built to live on very little water.","s":"A cactus is the perfect xerophyte, storing rain in its fat green stem.","p":"ZEER-uh-fyte","o":"Greek","y":9,"bp":58,"nt":"Open","ps":"noun","t":["championship","climatology","botany","ogreek"],"m":"zerophyte","sy":"xe.ro.phyte"},{"w":"xerothermic","d":"Marked by weather that is both hot and very dry.","s":"A long xerothermic spell shrank the lake to a cracked white pan.","p":"zeer-oh-THUR-mik","o":"Greek","y":8,"bp":64,"nt":"Open","ps":"adjective","t":["championship","climatology","weather","ogreek"],"m":"zerothermic","sy":"xe.ro.ther.mic"},{"w":"xerophilous","d":"Loving dry places and thriving where rain is scarce.","s":"Only xerophilous shrubs survive on that baked stony ridge.","p":"zih-ROF-ih-lus","o":"Greek","y":9,"bp":64,"nt":"Open","ps":"adjective","t":["championship","climatology","weather","ogreek"],"m":"zerophilous","sy":"xe.ro.phi.lous"},{"w":"xerosere","d":"The march of plant life that begins on bare, dry rock or sand.","s":"Lichens open the xerosere long before any grass takes hold.","p":"ZEER-uh-seer","o":"Greek","y":9,"bp":65,"nt":"Open","ps":"noun","t":["championship","soil science","botany","minerals","ogreek"],"m":"zerosere","sy":"xe.ro.sere"},{"w":"xenarthran","d":"A member of the group that includes sloths, anteaters and armadillos.","s":"The giant ground sloth was the largest xenarthran of them all.","p":"zeh-NAR-thrun","o":"Greek","y":8,"bp":67,"nt":"Open","ps":"noun","t":["championship","palaeontology","ogreek"],"m":"zenarthran","sy":"xen.ar.thran"},{"w":"xenograft","d":"A piece of tissue moved from one kind of animal into an animal of another kind.","s":"A pig heart valve placed in a person is the commonest xenograft of all.","p":"ZEN-uh-graft","o":"Greek","y":6,"bp":63,"nt":"Open","ps":"noun","t":["championship","immunology","body","animals","ogreek"],"m":"zenograft","sy":"xen.o.graft"},{"w":"xeroderma","d":"Abnormally dry, rough skin.","s":"Winter wind always brought on his xeroderma by December.","p":"zeer-uh-DER-muh","o":"Greek","y":8,"bp":67,"nt":"Open","ps":"noun","t":["championship","dermatology","body","ogreek"],"m":"zeroderma","sy":"xer.o.der.ma"},{"w":"xanthelasma","d":"A soft yellow patch of fat lying under the skin close to the eyelid.","s":"The xanthelasma near his eye led to a check of his cholesterol.","p":"zan-thuh-LAZ-muh","o":"Greek","y":9,"bp":70,"nt":"Open","ps":"noun","t":["championship","dermatology","body","ogreek"],"m":"zanthelasma","sy":"xan.the.las.ma"},{"w":"xanthoma","d":"A yellowish lump of fat laid down in the skin.","s":"A small xanthoma had formed on the tendon at the back of his ankle.","p":"zan-THOH-muh","o":"Greek","y":9,"bp":68,"nt":"Open","ps":"noun","t":["championship","dermatology","body","ogreek"],"m":"zanthoma","sy":"xan.tho.ma"},{"w":"xylograph","d":"A print taken from a design cut into a block of wood.","s":"An early xylograph of a saint hangs in the reading room.","p":"ZY-luh-graf","o":"Greek","y":8,"bp":66,"nt":"Open","ps":"noun","t":["championship","bibliography","ogreek"],"m":"zylograph","sy":"xy.lo.graph"}]'};
